package blockbranch.realistic;
import blockbranch.Blockbranch;import blockbranch.mixin.cubic.*;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.CompoundTag;import net.minecraft.util.RandomSource;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.chunk.ChunkGenerator;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.pieces.*;import net.minecraft.world.level.levelgen.structure.structures.OceanMonumentPieces;
/** Flooded outer sanctuary: two connected rings, four unequal landmarks and open water shafts. */
public final class ReimaginedSanctuaryPiece extends StructurePiece {
 public static final StructurePieceType TYPE=Registry.register(BuiltInRegistries.STRUCTURE_PIECE,Blockbranch.id("reimagined_sanctuary_v1"),(StructurePieceType)ReimaginedSanctuaryPiece::new);public static void initialize(){}
 private final int ox,oy,oz,xx,xz,zx,zz;
 private final int stonework,replacement;
 public static void fit(OceanMonumentPieces.MonumentBuilding core,int y){int dy=y-core.getBoundingBox().minY();core.move(0,dy,0);for(var child:((ReimaginedMonumentChildren)core).blockbranch$children())child.move(0,dy,0);}
 public ReimaginedSanctuaryPiece(OceanMonumentPieces.MonumentBuilding core){this(core,0);}
 public ReimaginedSanctuaryPiece(OceanMonumentPieces.MonumentBuilding core,int stonework){this(core,stonework,0);}
 public ReimaginedSanctuaryPiece(OceanMonumentPieces.MonumentBuilding core,int stonework,int replacement){super(TYPE,0,expanded(core.getBoundingBox()));if(stonework<0||stonework>1)throw new IllegalArgumentException("Unknown sanctuary stonework");this.stonework=stonework;if(replacement<0||replacement>1)throw new IllegalArgumentException("Unknown sanctuary replacement");this.replacement=replacement;var a=(ReimaginedPieceCoordinates)core;var o=a.blockbranch$local(0,0,0).immutable();var x=a.blockbranch$local(1,0,0).immutable();var z=a.blockbranch$local(0,0,1).immutable();ox=o.getX();oy=o.getY();oz=o.getZ();xx=x.getX()-ox;xz=x.getZ()-oz;zx=z.getX()-ox;zz=z.getZ()-oz;}
 private ReimaginedSanctuaryPiece(StructurePieceSerializationContext c,CompoundTag t){super(TYPE,t);if(t.contains("SanctuaryReplacement")&&!(t.get("SanctuaryReplacement") instanceof net.minecraft.nbt.IntTag))throw new IllegalArgumentException("Invalid sanctuary replacement tag");replacement=t.getIntOr("SanctuaryReplacement",0);if(replacement<0||replacement>1)throw new IllegalArgumentException("Unknown sanctuary replacement");if(t.contains("SanctuaryStonework")&&!(t.get("SanctuaryStonework") instanceof net.minecraft.nbt.IntTag))throw new IllegalArgumentException("Invalid sanctuary stonework tag");stonework=t.contains("SanctuaryStonework")?t.getIntOr("SanctuaryStonework",-1):0;if(stonework<0||stonework>1)throw new IllegalArgumentException("Unknown sanctuary stonework");int[] a=t.getIntArray("Basis").orElseThrow();if(t.getIntOr("LayoutDefinition",0)!=1||a.length!=7)throw new IllegalArgumentException("Invalid sanctuary");ox=a[0];oy=a[1];oz=a[2];xx=a[3];xz=a[4];zx=a[5];zz=a[6];if(Math.abs(xx)+Math.abs(xz)!=1||Math.abs(zx)+Math.abs(zz)!=1||xx*zx+xz*zz!=0)throw new IllegalArgumentException("Invalid sanctuary orientation");var a0=local(-15,-34,-15);var a1=local(72,36,72);var expected=new BoundingBox(Math.min(a0.getX(),a1.getX()),oy-34,Math.min(a0.getZ(),a1.getZ()),Math.max(a0.getX(),a1.getX()),oy+36,Math.max(a0.getZ(),a1.getZ()));if(!boundingBox.equals(expected))throw new IllegalArgumentException("Saved sanctuary bounds differ");}
 private static BoundingBox expanded(BoundingBox b){return new BoundingBox(b.minX()-15,b.minY()-34,b.minZ()-15,b.maxX()+15,b.minY()+36,b.maxZ()+15);}
 public BlockPos local(int x,int y,int z){return new BlockPos(ox+x*xx+z*zx,oy+y,oz+x*xz+z*zz);}
 @Override protected void addAdditionalSaveData(StructurePieceSerializationContext c,CompoundTag t){t.putInt("LayoutDefinition",1);if(stonework>0)t.putInt("SanctuaryStonework",stonework);if(replacement>0)t.putInt("SanctuaryReplacement",replacement);t.putIntArray("Basis",new int[]{ox,oy,oz,xx,xz,zx,zz});}
 @Override public void postProcess(WorldGenLevel level,StructureManager structures,ChunkGenerator generator,RandomSource random,BoundingBox clip,ChunkPos chunk,BlockPos pivot){if(replacement==1){SanctuaryReplacement.generate(new SanctuaryReplacement.Writer(){
   public void set(int x,int y,int z,net.minecraft.world.level.block.state.BlockState state){var p=local(x,y,z);if(clip.isInside(p)&&boundingBox.isInside(p))level.setBlock(p,state,2);}
   public net.minecraft.world.level.block.state.BlockState get(int x,int y,int z){var p=local(x,y,z);return clip.isInside(p)&&boundingBox.isInside(p)?level.getBlockState(p):null;}
   public Direction direction(int dx,int dz){int x=dx*xx+dz*zx,z=dx*xz+dz*zz;return x>0?Direction.EAST:x<0?Direction.WEST:z>0?Direction.SOUTH:Direction.NORTH;}
  });return;}var w=new Writer(level,clip);
  for(int y:new int[]{1,12}){hall(w,-12,y,-12,69,y+4,-6);hall(w,-12,y,63,69,y+4,69);hall(w,-12,y,-6,-6,y+4,63);hall(w,63,y,-6,69,y+4,63);}
  tower(w,-14,-14,22,Blocks.PRISMARINE_BRICKS);tower(w,63,-14,29,Blocks.DARK_PRISMARINE);tower(w,-14,63,34,Blocks.PRISMARINE);tower(w,63,63,25,Blocks.PRISMARINE_BRICKS);
  // Open approach joins the original native entrance without touching its room graph, gold or elder spawns.
  w.box(24,-1,-12,33,0,-1,Blocks.PRISMARINE_BRICKS);w.box(25,1,-12,32,9,-1,Blocks.WATER);w.box(24,1,-12,24,9,-1,Blocks.DARK_PRISMARINE);w.box(33,1,-12,33,9,-1,Blocks.DARK_PRISMARINE);w.box(24,10,-12,33,10,-1,Blocks.PRISMARINE_BRICKS);
  w.box(24,1,-11,24,4,-7,Blocks.WATER);w.box(33,1,-11,33,4,-7,Blocks.WATER);
  // Native-looking piers reach the bounded admitted seabed, with no floating lower ring.
  for(int t=-12;t<=69;t+=9)for(int side:new int[]{-10,67}){w.box(t,-34,side,t+1,0,side+1,Blocks.PRISMARINE);w.box(side,-34,t,side+1,0,t+1,Blocks.PRISMARINE);}
 }
 private void hall(Writer w,int x,int y,int z,int mx,int my,int mz){w.box(x,y-1,z,mx,my,mz,Blocks.PRISMARINE_BRICKS);w.box(x+1,y,z+1,mx-1,my-1,mz-1,Blocks.WATER);if(mx-x>mz-z)for(int a=x+4;a<mx-2;a+=8){w.box(a,y+1,z,a+2,y+2,z,Blocks.WATER);w.box(a,y+1,mz,a+2,y+2,mz,Blocks.WATER);w.block(a,y-1,(z+mz)/2,Blocks.SEA_LANTERN);}else for(int a=z+4;a<mz-2;a+=8){w.box(x,y+1,a,x,y+2,a+2,Blocks.WATER);w.box(mx,y+1,a,mx,y+2,a+2,Blocks.WATER);w.block((x+mx)/2,y-1,a,Blocks.SEA_LANTERN);}if(stonework==1)SanctuaryStonework.hall(w::block,x,y,z,mx,my,mz);}
 private void tower(Writer w,int x,int z,int h,Block material){w.box(x,-34,z,x+8,h,z+8,material);w.box(x+1,1,z+1,x+7,h-1,z+7,Blocks.WATER);for(int y:new int[]{1,12}){w.box(x+2,y,z,x+6,y+3,z+8,Blocks.WATER);w.box(x,y,z+2,x+8,y+3,z+6,Blocks.WATER);}for(int y=6;y<h;y+=6){w.box(x,y,z,x+8,y,z,Blocks.DARK_PRISMARINE);w.box(x,y,z+8,x+8,y,z+8,Blocks.DARK_PRISMARINE);w.block(x+4,y,z,Blocks.SEA_LANTERN);w.block(x+4,y,z+8,Blocks.SEA_LANTERN);}w.box(x+2,h,z+2,x+6,h,z+6,Blocks.WATER);if(stonework==0)for(int[] p:new int[][]{{0,0},{8,0},{0,8},{8,8}})w.box(x+p[0],h+1,z+p[1],x+p[0],h+2,z+p[1],Blocks.PRISMARINE_BRICKS);if(stonework==1)SanctuaryStonework.tower(w::block,x,z,h);}
 private final class Writer{final WorldGenLevel level;final BoundingBox clip;Writer(WorldGenLevel l,BoundingBox c){level=l;clip=c;}void block(int x,int y,int z,Block b){if(x>=0&&x<=57&&z>=0&&z<=57)return;var at=local(x,y,z);if(clip.isInside(at))level.setBlock(at,b.defaultBlockState(),2);}void box(int x,int y,int z,int mx,int my,int mz,Block b){for(int xx=x;xx<=mx;xx++)for(int zz=z;zz<=mz;zz++)for(int yy=y;yy<=my;yy++)block(xx,yy,zz,b);}}
}
